-- Use existing enchantments with the same socket-bonus stat and a level-60 magnitude.
CREATE TEMPORARY TABLE `_coa_karazhan_socket_bonuses` (
    `entry` INT UNSIGNED PRIMARY KEY,
    `socket_bonus` INT UNSIGNED NOT NULL
) ENGINE=InnoDB;

DELETE FROM `_coa_karazhan_socket_bonuses`;

UPDATE `item_template` AS `item`
JOIN `_coa_karazhan_socket_bonuses` AS `socket` ON `socket`.`entry` = `item`.`entry`
SET `item`.`socketBonus` = `socket`.`socket_bonus`;

DROP TEMPORARY TABLE `_coa_karazhan_socket_bonuses`;
